components.css:
.ds-theme { display: inline-flex; align-items: center; justify-content: center; min-height: 44px; background: transparent; color: var(--color-ink-strong, #211c16); border: 1px solid var(--color-rule, color-mix(in srgb, var(--color-ink-muted, #675645) 44%, transparent)); border-radius: 4px; cursor: pointer; transition: all 200ms; }
.ds-theme:hover { background: var(--color-signal-soft, rgba(164, 54, 32, 0.12)); border-color: color-mix(in srgb, var(--color-signal, #a43620) 40%, transparent); }
:host-context(.dark) .ds-theme:hover { border-color: color-mix(in srgb, var(--color-signal, #a43620) 42%, transparent); }
.ds-theme:focus-visible { outline: 2px solid var(--color-signal, #a43620); outline-offset: 2px; box-shadow: 0 0 0 2px var(--color-parchment, #f5eddb); }
.ds-theme { width: 44px; height: 44px; padding: 0; }
.ds-theme svg { width: 20px; height: 20px; stroke-width: 2; }
.ds-sun, :host-context(.dark) .ds-moon { display: none; }
:host-context(.dark) .ds-sun { display: block; opacity: 0.95; }

.ds-language { display: inline-flex; align-items: center; justify-content: center; min-height: 44px; background: transparent; color: var(--color-ink-strong, #211c16); border: 1px solid var(--color-rule, color-mix(in srgb, var(--color-ink-muted, #675645) 44%, transparent)); border-radius: 4px; cursor: pointer; transition: all 200ms; }
.ds-language:hover { background: var(--color-signal-soft, rgba(164, 54, 32, 0.12)); border-color: color-mix(in srgb, var(--color-signal, #a43620) 40%, transparent); }
:host-context(.dark) .ds-language:hover { border-color: color-mix(in srgb, var(--color-signal, #a43620) 42%, transparent); }
.ds-language:focus-visible { outline: 2px solid var(--color-signal, #a43620); outline-offset: 2px; box-shadow: 0 0 0 2px var(--color-parchment, #f5eddb); }
.ds-language { height: 44px; padding: 0 0.625rem; gap: 0.25rem; font: 0.75rem / 1.333333 var(--font-mono, JetBrains Mono, ui-monospace, monospace); }
.ds-language span { color: var(--color-ink-faint, #705947); }
.ds-language-separator { opacity: 0.4; }
.ds-language strong { color: var(--color-signal, #a43620); font-weight: 700; }

.ds-masthead-nav { display: flex; flex-wrap: wrap; column-gap: 0.75rem; color: var(--color-ink, #3c3025); font: 0.875rem / 1.428571 var(--font-body, DM Sans, ui-sans-serif, system-ui, sans-serif); }
.ds-masthead-nav a { display: inline-flex; align-items: center; min-height: 44px; color: inherit; text-decoration: underline; text-underline-offset: 0.25em; }
.ds-masthead-nav a:hover { color: var(--color-signal, #a43620); }
.ds-masthead-nav a:focus-visible { outline: 2px solid var(--color-signal, #a43620); outline-offset: 4px; }
@media (min-width: 768px) { .ds-masthead-nav { column-gap: 1.25rem; } }

.ds-editorial-case { padding: 1.75rem 0; border-top: 1px solid var(--color-rule, color-mix(in srgb, var(--color-ink-muted, #675645) 44%, transparent)); color: var(--color-ink-strong, #211c16); }
.ds-editorial-case h3 { margin: 0 0 0.25rem; font: 600 clamp(2.75rem, 6.8vw, 5.875rem) / 0.98 var(--font-display, Newsreader, ui-serif, Georgia, "Times New Roman", serif); letter-spacing: -0.025em; }
.ds-editorial-case p { margin: 0; color: var(--color-ink-muted, #675645); font: 0.875rem / 1.428571 var(--font-body, DM Sans, ui-sans-serif, system-ui, sans-serif); }
.ds-editorial-case .ds-case-result { display: flex; flex-wrap: wrap; align-items: center; gap: 0.25rem 1.25rem; margin-top: 1rem; color: var(--color-ink-strong, #211c16); font: 500 1rem / 1.35 var(--font-body, DM Sans, ui-sans-serif, system-ui, sans-serif); }
.ds-case-result strong { color: var(--color-signal, #a43620); font: 500 clamp(5.5rem, 10.5vw, 9.5rem) / 1 var(--font-display, Newsreader, ui-serif, Georgia, "Times New Roman", serif); font-variant-numeric: lining-nums; letter-spacing: -0.055em; white-space: nowrap; }
.ds-case-result span { max-width: 23ch; }
@media (min-width: 768px) { .ds-editorial-case { padding: 2rem 0; } }

.ds-architecture { margin: 0; padding-top: 1rem; border-top: 1px solid var(--color-ink-muted, #675645); color: var(--color-ink, #3c3025); }
.ds-architecture figcaption { margin-bottom: 1.25rem; color: var(--color-ink-strong, #211c16); font: 500 1.25rem / 1.4 var(--font-display, Newsreader, ui-serif, Georgia, "Times New Roman", serif); }
.ds-architecture p { margin: 1rem 0 0; padding-top: 0.5rem; border-top: 1px solid var(--color-rule, color-mix(in srgb, var(--color-ink-muted, #675645) 44%, transparent)); color: var(--color-ink-muted, #675645); font: 0.875rem / 1.428571 var(--font-body, DM Sans, ui-sans-serif, system-ui, sans-serif); }
.ds-flow { display: grid; grid-template-columns: minmax(0, 1fr) auto minmax(0, 1.25fr); align-items: stretch; font: 1rem / 1.5 var(--font-display, Newsreader, ui-serif, Georgia, "Times New Roman", serif); }
.ds-flow span { display: flex; align-items: center; padding: 0.75rem 0.625rem; border: 1px solid var(--color-rule, color-mix(in srgb, var(--color-ink-muted, #675645) 44%, transparent)); }
.ds-flow svg { width: 1rem; height: 1rem; margin: 0 0.25rem; align-self: center; color: var(--color-signal, #a43620); }
.ds-flow .ds-flow-down { grid-column: 3; margin: 0.25rem 0; justify-self: center; }
.ds-flow-last { grid-column: 3; }
@media (min-width: 768px) { .ds-flow { font-size: 1.125rem; } }

.ds-disclosure { font: 0.875rem / 1.625 var(--font-body, DM Sans, ui-sans-serif, system-ui, sans-serif); color: var(--color-ink-muted, #675645); }
.ds-disclosure summary { display: flex; align-items: center; gap: 0.5rem; min-height: 44px; width: fit-content; cursor: pointer; list-style: none; font-weight: 600; color: var(--color-signal, #a43620); text-underline-offset: 0.25rem; }
.ds-disclosure summary::-webkit-details-marker { display: none; }
.ds-disclosure summary:hover { text-decoration: underline; }
.ds-disclosure summary:focus-visible { outline: 2px solid var(--color-signal, #a43620); outline-offset: 4px; }
.ds-disclosure summary svg { width: 1rem; height: 1rem; }
.ds-disclosure[open] summary svg { transform: rotate(180deg); }
.ds-disclosure p { margin: 0.5rem 0 1rem; }
